import multiprocessing as mp


def 平方(位子, 下标, 数):
    位子[下标] = 数 * 数


def 主流程():
    起点 = [{nums}]
    位子 = mp.Array('i', 3)
    孩子们 = []
    for i in range(3):
        p = mp.Process(target=平方, args=(位子, i, 起点[i]))
        p.start()
        孩子们.append(p)
    for p in 孩子们:
        p.join()
    for i in range(3):
        print(位子[i])


if __name__ == '__main__':
    主流程()
